    cols = [runs([r for r in range(h) if grid[r][c] == fg]) for c in range(w)]

    major_rows = {r for r, gs in enumerate(rows) if any(len(g) >= 5 for g in gs)}
    major_cols = {c for c, gs in enumerate(cols) if any(len(g) >= 5 for g in gs)}

    out = [[bg] * w for _ in range(h)]

    # Keep the main vertical strokes, joining short interruptions.
    for c in major_cols:
        positions = [r for r in range(h) if grid[r][c] == fg]
        for r in positions:
            out[r][c] = fg
        for a, b in zip(positions, positions[1:]):
            if b - a <= 4:
                for r in range(a, b + 1):
                    out[r][c] = fg

    # Keep horizontal segments, and bridge short gaps when they meet a main
    # vertical stroke.
    for r, gs in enumerate(rows):
        if r in major_rows:
            for g in gs:
                if len(g) >= 2:
                    for c in g:
                        out[r][c] = fg
            for left, right in zip(gs, gs[1:]):
                gap = right[0] - left[-1] - 1
                if 1 <= gap <= 3 and (
                    left[-1] in major_cols or right[0] in major_cols
                ):
                    for c in range(left[-1], right[0] + 1):
                        out[r][c] = fg
        else:
            for g in gs:
                if any(c in major_cols for c in g):
                    for c in g:
                        out[r][c] = fg

    return out
